DROP TABLE IF EXISTS `outsource_order_delivery`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `outsource_order_delivery` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` bigint DEFAULT NULL COMMENT '订单ID',
  `warehouse_id` bigint DEFAULT NULL COMMENT '收货仓库ID',
  `delivery_date` date DEFAULT NULL COMMENT '发货日期',
  `product_id` bigint DEFAULT NULL COMMENT '产品ID(关联outsource_order_product)',
  `product_master_id` bigint DEFAULT NULL COMMENT '关联产品主数据ID(product.id)',
  `quality_type` varchar(20) DEFAULT NULL COMMENT '退不良规格(A/B/C/DEFECT)',
  `quantity` decimal(18,0) DEFAULT '0',
  `delivery_type` varchar(20) DEFAULT 'DELIVERY' COMMENT 'DELIVERY正常交货/DEFECT_RETURN退不良',
  `a_qty` decimal(18,0) DEFAULT '0',
  `b_qty` decimal(18,0) DEFAULT '0',
  `c_qty` decimal(18,0) DEFAULT '0',
  `defect_qty` decimal(18,0) DEFAULT '0',
  `source_type` varchar(20) DEFAULT 'DELIVERY' COMMENT '来源类型: DELIVERY普通交货/RETURN_DEFECT委外退货/AFTER_SALE收费售后',
  `tracking_no` varchar(100) DEFAULT NULL COMMENT '物流单号',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `attach_url` varchar(500) DEFAULT NULL COMMENT '附件URL',
  `status` varchar(20) DEFAULT 'NORMAL' COMMENT '状态: NORMAL/REVERSED',
  `is_reverse` tinyint DEFAULT '0' COMMENT '是否退不良红冲记录：1=退不良(数量为负) / 0=普通交货',
  `company_id` bigint DEFAULT NULL COMMENT '公司ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_warehouse_id` (`warehouse_id`),
  KEY `idx_company_id` (`company_id`)
) ENGINE=InnoDB AUTO_INCREMENT=143 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='外协订单发货记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

