DROP TABLE IF EXISTS `outsource_return_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `outsource_return_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(50) NOT NULL COMMENT '退货单号',
  `factory_id` bigint DEFAULT NULL COMMENT '加工厂ID',
  `return_type` varchar(20) NOT NULL DEFAULT 'DEFECT' COMMENT '退货类型: DEFECT不良退货/REPAIR维修退货',
  `order_id` bigint DEFAULT NULL COMMENT '关联加工单ID',
  `warehouse_id` bigint DEFAULT NULL COMMENT '成品出库仓',
  `return_date` date DEFAULT NULL COMMENT '退货日期',
  `status` varchar(20) DEFAULT 'AUDITED' COMMENT '状态(草稿-审核-取消审核)',
  `auditor_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `auditor_name` varchar(50) DEFAULT NULL COMMENT '审核人姓名',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `charge_flag` tinyint DEFAULT '0' COMMENT '工厂收费(加工厂向我方收取): 0否 1是(审核生成一条我方付给加工厂的正向应付)。不良退货必须 0；维修退货必须 1',
  `charge_type` varchar(20) DEFAULT NULL COMMENT '收费类型: REWORK返工费/FREIGHT运费/INSPECTION检测费/EXCESS_LOSS超损赔偿/OTHER其他',
  `charge_amount` decimal(18,2) DEFAULT '0.00' COMMENT '收费金额(手工填写，审核后生成正向应付，与退料负向冲减分开记账)',
  `charge_reason` varchar(200) DEFAULT NULL COMMENT '收费说明(原因备注)',
  `company_id` bigint DEFAULT NULL COMMENT '公司ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `source_delivery_id` bigint DEFAULT NULL COMMENT '来源交货记录ID(outsource_order_delivery.id)',
  `closed_flag` tinyint DEFAULT '0' COMMENT '结案：0未结案 1已结案（仅维修退货用：未返回=0 后才能结案）',
  `closed_time` datetime DEFAULT NULL COMMENT '结案时间',
  `closed_by` varchar(50) DEFAULT NULL COMMENT '结案人',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_factory_id` (`factory_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_source_delivery_id` (`source_delivery_id`)
) ENGINE=InnoDB AUTO_INCREMENT=265 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='委外退货单';
/*!40101 SET character_set_client = @saved_cs_client */;

